CREATE TABLE conversations (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sequence INTEGER NOT NULL, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL DEFAULT '', state TEXT NOT NULL CHECK(state IN ('streaming','completed','cancelled','failed')), reply_to_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, supersedes_message_id TEXT REFERENCES messages(id) ON DELETE SET NULL, provider TEXT, profile_id TEXT, model TEXT, usage_json TEXT, error_code TEXT, completion_reason TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, superseded INTEGER NOT NULL DEFAULT 0, UNIQUE(conversation_id,sequence));
CREATE UNIQUE INDEX idx_messages_active_lineage ON messages(conversation_id,reply_to_message_id) WHERE role='assistant' AND superseded=0;
CREATE TABLE message_citations (id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, label TEXT NOT NULL, source_id TEXT NOT NULL REFERENCES sources(id) ON DELETE CASCADE, source_chunk_id TEXT REFERENCES source_chunks(id) ON DELETE SET NULL, source_display_name TEXT NOT NULL, source_kind TEXT NOT NULL, locator_json TEXT NOT NULL, quote TEXT, created_at TEXT NOT NULL, UNIQUE(message_id,label));
